import{_ as n,o as s,c as a,a2 as t}from"./chunks/framework.C9xbT7QL.js";const u=JSON.parse('{"title":"Component Model","description":"Every runtime component in hookshot — what it does, what it owns, what depends on it","frontmatter":{"title":"Component Model","description":"Every runtime component in hookshot — what it does, what it owns, what depends on it","audience":["contributor","architect"]},"headers":[],"relativePath":"architecture/component-model.md","filePath":"architecture/component-model.md","lastUpdated":1775245357000}'),r={name:"architecture/component-model.md"};function o(i,e,p,c,d,l){return s(),a("div",null,[...e[0]||(e[0]=[t(`<h1 id="component-model" tabindex="-1">Component Model <a class="header-anchor" href="#component-model" aria-label="Permalink to &quot;Component Model&quot;">​</a></h1><p>Hookshot is a single Node.js process (or <a href="./../guides/operator/workers-and-scaling">multiple workers</a>) with these major components:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes catppuccin-latte catppuccin-frappe vp-code" tabindex="0"><code><span class="line"><span>┌─────────────────────────────────────────────────────────────┐</span></span>
<span class="line"><span>│                    BridgeApp (entry point)                   │</span></span>
<span class="line"><span>│                    src/App/BridgeApp.ts                      │</span></span>
<span class="line"><span>├─────────────────────────────────────────────────────────────┤</span></span>
<span class="line"><span>│                                                             │</span></span>
<span class="line"><span>│  ┌──────────┐  ┌──────────────┐  ┌────────────────────┐    │</span></span>
<span class="line"><span>│  │ Bridge   │  │ Connection   │  │ ListenerService    │    │</span></span>
<span class="line"><span>│  │          │◄─┤ Manager      │  │ (HTTP listeners)   │    │</span></span>
<span class="line"><span>│  │ Event    │  │              │  │                    │    │</span></span>
<span class="line"><span>│  │ dispatch │  │ 15 Connection│  │ ┌──────────────┐  │    │</span></span>
<span class="line"><span>│  │          │  │ types        │  │ │ Webhooks.ts  │  │    │</span></span>
<span class="line"><span>│  └────┬─────┘  └──────────────┘  │ │ Express      │  │    │</span></span>
<span class="line"><span>│       │                          │ │ router       │  │    │</span></span>
<span class="line"><span>│  ┌────▼─────┐  ┌──────────────┐  │ └──────────────┘  │    │</span></span>
<span class="line"><span>│  │ Message  │  │ MatrixSender │  └────────────────────┘    │</span></span>
<span class="line"><span>│  │ Queue    │◄─┤              │                             │</span></span>
<span class="line"><span>│  │ LocalMQ  │  │ Send to HS   │  ┌────────────────────┐    │</span></span>
<span class="line"><span>│  │ or Redis │  └──────────────┘  │ BotUsersManager    │    │</span></span>
<span class="line"><span>│  └──────────┘                    │ (user identities)  │    │</span></span>
<span class="line"><span>│                                  └────────────────────┘    │</span></span>
<span class="line"><span>│  ┌──────────┐  ┌──────────────┐  ┌────────────────────┐    │</span></span>
<span class="line"><span>│  │ Storage  │  │ UserToken    │  │ BridgeWidgetApi    │    │</span></span>
<span class="line"><span>│  │ Provider │  │ Store        │  │ (REST + Widget)    │    │</span></span>
<span class="line"><span>│  │ Mem/Redis│  │ (encrypted)  │  └────────────────────┘    │</span></span>
<span class="line"><span>│  └──────────┘  └──────────────┘                             │</span></span>
<span class="line"><span>│                                  ┌────────────────────┐    │</span></span>
<span class="line"><span>│  ┌──────────┐  ┌──────────────┐  │ Rust NAPI modules  │    │</span></span>
<span class="line"><span>│  │ Feed     │  │ Hound        │  │ feeds, tokens,     │    │</span></span>
<span class="line"><span>│  │ Reader   │  │ Reader       │  │ format, permissions│    │</span></span>
<span class="line"><span>│  └──────────┘  └──────────────┘  └────────────────────┘    │</span></span>
<span class="line"><span>└─────────────────────────────────────────────────────────────┘</span></span></code></pre></div><h2 id="components" tabindex="-1">Components <a class="header-anchor" href="#components" aria-label="Permalink to &quot;Components&quot;">​</a></h2><h3 id="bridgeapp-—-entry-point" tabindex="-1">BridgeApp — Entry point <a class="header-anchor" href="#bridgeapp-—-entry-point" aria-label="Permalink to &quot;BridgeApp — Entry point&quot;">​</a></h3><p><strong>File:</strong> <code>src/App/BridgeApp.ts</code><strong>Owns:</strong> Startup sequence, dependency wiring <strong>Creates:</strong> All other components</p><p>Initializes the system in <a href="./../understand/event-lifecycle">22 steps</a>: listener → logging → appservice → storage → token store → Bridge → connections → feed polling → webhook routing → appservice start.</p><h3 id="bridge-—-event-dispatch-core" tabindex="-1">Bridge — Event dispatch core <a class="header-anchor" href="#bridge-—-event-dispatch-core" aria-label="Permalink to &quot;Bridge — Event dispatch core&quot;">​</a></h3><p><strong>File:</strong> <code>src/Bridge.ts</code> (~2,100 lines) <strong>Owns:</strong> Matrix event reception, <a href="./state-and-storage#message-queue">message queue</a> subscriptions, webhook handler bindings <strong>Depends on:</strong> ConnectionManager, MessageQueue, MatrixSender, BotUsersManager</p><p>The central nervous system. Receives Matrix events via <a href="./../reference/matrix-spec-map">appservice API</a>, receives webhook events via message queue, and dispatches both to the appropriate <a href="./connections">connections</a>.</p><p>Binds <a href="./../understand/event-lifecycle#step-by-step">45+ handler functions</a> mapping message queue topics (e.g., <code>github.issues.opened</code>) to connection methods (e.g., <code>onIssueCreated</code>).</p><h3 id="connectionmanager-—-connection-registry" tabindex="-1">ConnectionManager — Connection registry <a class="header-anchor" href="#connectionmanager-—-connection-registry" aria-label="Permalink to &quot;ConnectionManager — Connection registry&quot;">​</a></h3><p><strong>File:</strong> <code>src/ConnectionManager.ts</code> (~924 lines) <strong>Owns:</strong> Connection lifecycle, lookup, <a href="./../reference/provisioning-api">provisioning</a><strong>Depends on:</strong> All connection classes, StorageProvider, UserTokenStore</p><p>Maintains a flat array of all active <a href="./connections">connections</a>. Provides lookup by room, service, and resource. Handles connection creation from all four <a href="./../understand/integration-model#four-ways-to-create-a-connection">provisioning paths</a>.</p><h3 id="connection-types-—-per-service-logic" tabindex="-1">Connection types — Per-service logic <a class="header-anchor" href="#connection-types-—-per-service-logic" aria-label="Permalink to &quot;Connection types — Per-service logic&quot;">​</a></h3><p><strong>Files:</strong> <code>src/Connections/*.ts</code> (15 classes) <strong>Own:</strong> Service-specific event handling, <a href="./../reference/bot-commands">bot commands</a>, message formatting <strong>Depend on:</strong> External service clients, MatrixSender</p><p>Each connection type implements <code>IConnection</code> and handles events for one service. See <a href="./connections">Connections</a> for the abstraction and <a href="./../integrations/overview">Integration Overview</a> for all types.</p><h3 id="listenerservice-—-http-server" tabindex="-1">ListenerService — HTTP server <a class="header-anchor" href="#listenerservice-—-http-server" aria-label="Permalink to &quot;ListenerService — HTTP server&quot;">​</a></h3><p><strong>File:</strong> <code>src/ListenerService.ts</code> (~141 lines) <strong>Owns:</strong> Express HTTP listeners, port binding, <a href="./../guides/operator/monitoring#health-probes">health probes</a> (<code>/live</code>, <code>/ready</code>) <strong>Depends on:</strong> Configuration</p><p>Manages multiple HTTP listeners, each binding a subset of resources (webhooks, widgets, metrics, provisioning). See <a href="./../guides/operator/configuration#listeners-required">listener configuration</a>.</p><h3 id="webhooks-—-inbound-routing" tabindex="-1">Webhooks — Inbound routing <a class="header-anchor" href="#webhooks-—-inbound-routing" aria-label="Permalink to &quot;Webhooks — Inbound routing&quot;">​</a></h3><p><strong>File:</strong> <code>src/Webhooks.ts</code> (~166 lines) <strong>Owns:</strong> Express router, service-specific sub-routers <strong>Depends on:</strong> MessageQueue, service routers</p><p>Routes incoming HTTP webhooks to the correct service router (<code>/github</code> → GitHubWebhooksRouter, <code>/gitlab</code> → GitLabWebhooksRouter, etc.). Each router verifies signatures and publishes events to the <a href="./state-and-storage#message-queue">message queue</a>.</p><h3 id="matrixsender-—-outbound-messages" tabindex="-1">MatrixSender — Outbound messages <a class="header-anchor" href="#matrixsender-—-outbound-messages" aria-label="Permalink to &quot;MatrixSender — Outbound messages&quot;">​</a></h3><p><strong>File:</strong> <code>src/MatrixSender.ts</code> (~139 lines) <strong>Owns:</strong> Matrix message delivery <strong>Depends on:</strong> MessageQueue, Appservice (intents)</p><p>Listens on <code>matrix.message</code> queue topic. Sends events to the homeserver via bot <a href="./../understand/glossary#matrix-concepts">intents</a>. Handles <a href="./../guides/operator/encryption">encryption</a> if configured.</p><h3 id="messagequeue-—-internal-async-routing" tabindex="-1">MessageQueue — Internal async routing <a class="header-anchor" href="#messagequeue-—-internal-async-routing" aria-label="Permalink to &quot;MessageQueue — Internal async routing&quot;">​</a></h3><p><strong>Files:</strong> <code>src/messageQueue/</code> (5 files) <strong>Owns:</strong> Event routing between components <strong>Implementations:</strong> <a href="./state-and-storage#localmq-default">LocalMQ</a> (in-process) or <a href="./state-and-storage#redismq-worker-mode">RedisMQ</a> (multi-worker)</p><h3 id="storageprovider-—-deduplication-state" tabindex="-1">StorageProvider — Deduplication state <a class="header-anchor" href="#storageprovider-—-deduplication-state" aria-label="Permalink to &quot;StorageProvider — Deduplication state&quot;">​</a></h3><p><strong>Files:</strong> <code>src/stores/</code> (3 files) <strong>Owns:</strong> Tracking processed events to prevent duplicates <strong>Implementations:</strong> <a href="./state-and-storage#storage-providers">MemoryStorageProvider or RedisStorageProvider</a></p><h3 id="usertokenstore-—-credential-management" tabindex="-1">UserTokenStore — Credential management <a class="header-anchor" href="#usertokenstore-—-credential-management" aria-label="Permalink to &quot;UserTokenStore — Credential management&quot;">​</a></h3><p><strong>Owns:</strong> OAuth tokens, personal access tokens, encrypted storage <strong>Depends on:</strong> <code>passFile</code> RSA key (Rust <a href="./../understand/trust-and-boundaries#token-store">token encryption</a>)</p><h3 id="botusersmanager-—-user-identities" tabindex="-1">BotUsersManager — User identities <a class="header-anchor" href="#botusersmanager-—-user-identities" aria-label="Permalink to &quot;BotUsersManager — User identities&quot;">​</a></h3><p><strong>File:</strong> <code>src/managers/BotUsersManager.ts</code><strong>Owns:</strong> Bot user registration, room membership, <a href="./../guides/operator/service-bots">service bots</a><strong>Depends on:</strong> Appservice</p><h3 id="bridgewidgetapi-—-rest-api-widget" tabindex="-1">BridgeWidgetApi — REST API + Widget <a class="header-anchor" href="#bridgewidgetapi-—-rest-api-widget" aria-label="Permalink to &quot;BridgeWidgetApi — REST API + Widget&quot;">​</a></h3><p><strong>File:</strong> <code>src/widgets/BridgeWidgetApi.ts</code><strong>Owns:</strong> <a href="./../reference/provisioning-api">Provisioning API</a> endpoints, widget frontend serving <strong>Depends on:</strong> ConnectionManager, UserTokenStore</p><h3 id="feedreader-houndreader-—-polling-services" tabindex="-1">FeedReader / HoundReader — Polling services <a class="header-anchor" href="#feedreader-houndreader-—-polling-services" aria-label="Permalink to &quot;FeedReader / HoundReader — Polling services&quot;">​</a></h3><p><strong>Owns:</strong> Periodic polling for <a href="./../integrations/feeds">RSS/Atom feeds</a> and <a href="./../integrations/challengehound">ChallengeHound</a><strong>Depends on:</strong> Rust feed parser (NAPI), MessageQueue</p><h3 id="rust-napi-modules" tabindex="-1">Rust NAPI modules <a class="header-anchor" href="#rust-napi-modules" aria-label="Permalink to &quot;Rust NAPI modules&quot;">​</a></h3><p><strong>Files:</strong> <code>src/*.rs</code>, <code>src/**/*.rs</code><strong>Owns:</strong> Performance-critical operations</p><table tabindex="0"><thead><tr><th>Module</th><th>Purpose</th></tr></thead><tbody><tr><td><code>feeds/parser.rs</code></td><td>RSS/Atom feed parsing</td></tr><tr><td><code>tokens/mod.rs</code></td><td>Token encryption/decryption</td></tr><tr><td><code>format_util.rs</code></td><td>Message formatting, HTML sanitization</td></tr><tr><td><code>config/permissions.rs</code></td><td><a href="./../understand/trust-and-boundaries#permission-system">Permission checking</a></td></tr><tr><td><code>github/types.rs</code></td><td>GitHub type utilities</td></tr><tr><td><code>jira/types.rs</code>, <code>jira/utils.rs</code></td><td>JIRA utilities</td></tr></tbody></table><p>See <a href="./connections#adding-a-new-connection-type">Connections: Rust boundary</a> for the NAPI interface pattern.</p><h2 id="startup-sequence" tabindex="-1">Startup sequence <a class="header-anchor" href="#startup-sequence" aria-label="Permalink to &quot;Startup sequence&quot;">​</a></h2><p>See <a href="./../understand/event-lifecycle">Event Lifecycle</a> for the full 22-step startup. Key dependency order:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes catppuccin-latte catppuccin-frappe vp-code" tabindex="0"><code><span class="line"><span>Storage → Queue → Homeserver check → BotUsers → GitHub/Figma init</span></span>
<span class="line"><span>→ ConnectionManager → Event handlers → Room processing (concurrency: 2)</span></span>
<span class="line"><span>→ Widget API → Metrics → FeedReader → Webhooks → Appservice.begin()</span></span></code></pre></div><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><p><strong>Concepts:</strong> <a href="./../understand/event-lifecycle">Event Lifecycle</a> · <a href="./../understand/integration-model">Integration Model</a> · <a href="./../understand/trust-and-boundaries">Trust and Boundaries</a></p><p><strong>Architecture:</strong> <a href="./connections">Connections</a> · <a href="./state-and-storage">State and Storage</a></p><p><strong>Reference:</strong> <a href="./../reference/provisioning-api">Provisioning API</a> · <a href="./../reference/bot-commands">Bot Commands</a> · <a href="./../reference/matrix-spec-map">Matrix Spec Map</a></p><p><strong>Operator:</strong> <a href="./../guides/operator/configuration">Configuration</a> · <a href="./../guides/operator/workers-and-scaling">Workers</a> · <a href="./../guides/operator/monitoring">Monitoring</a></p>`,50)])])}const h=n(r,[["render",o]]);export{u as __pageData,h as default};
